25	        dead_controller: PlayerId,
26	        /// Last-known information captured before zone change clears battlefield state.
27	        dead_damaged_by: Vec<ObjectId>,
28	        dead_toughness: i32,
29	        description: String,
30	    },
31	    /// A creature entering the battlefield trigger.
32	    EnteredBattlefield {
33	        object_id: ObjectId,
34	        card_id: CardId,
35	        controller: PlayerId,
36	        description: String,
37	    },
38	    /// A "whenever a creature enters the battlefield" ETB-watch trigger on another permanent.
39	    EnterWatch {
40	        watcher_id: ObjectId,
41	        watcher_card_id: CardId,
42	        controller: PlayerId,
43	        entered_id: ObjectId,
44	        entered_controller: PlayerId,
45	        description: String,
46	    },
47	    /// A creature dealt combat damage to a player.
48	    CombatDamageToPlayer {
49	        creature_id: ObjectId,
50	        creature_card_id: CardId,
51	        controller: PlayerId,
52	        damaged_player: PlayerId,
53	        amount: u32,
